SELECT AVG((average_Medicare_allowed_amt - average_Medicare_payment_amt)) AS `avg:Calculation_9940518082838207:ok`, AVG(average_Medicare_allowed_amt) AS `avg:average_Medicare_allowed_amt:ok`, AVG(average_Medicare_payment_amt) AS `avg:average_Medicare_payment_amt:ok`, AVG(average_submitted_chrg_amt) AS `avg:average_submitted_chrg_amt:ok`, hcpcs_description AS hcpcs_description FROM taxpayer WHERE ((hcpcs_description = 'Initial hospital care') AND (nppes_provider_first_name = 'JOHN') AND (nppes_provider_last_org_name = 'HOLDER') AND (nppes_provider_state = 'WA')) GROUP BY hcpcs_description;
